# -*- coding: utf-8 -*-
"""أدوات تسويق ودراسة سوق متقدمة (تدعم رفع الملفات)."""
from biz_tools import F, S, add, CATS, T
PD="const dt=s=>{const d=new Date(s);return isNaN(d)?null:d};const sum=a=>a.reduce((s,x)=>s+x,0);const mean=a=>a.length?sum(a)/a.length:0;const sd=a=>{const m=mean(a);return Math.sqrt(mean(a.map(x=>(x-m)**2)))};const pct=(a,b)=>b?a/b*100:0;"

add('campaign-performance-analyzer','marketing','📣','محلل أداء الحملات الإعلانية (ارفع تقرير الإعلانات)','ارفع تقرير الحملات لتحصل على CTR وCPC وCPA وROAS لكل حملة ومنصة، مع توصيات الإيقاف والتوسّع وإعادة توزيع الميزانية.',
 [F('d','تقرير الحملات (حملة | منصة | إنفاق | ظهور | نقرات | تحويلات | إيراد)','textarea','عرض الجمعة | Meta | 8000 | 420000 | 9800 | 310 | 38000\nريتارجتنج | Meta | 3000 | 90000 | 3100 | 140 | 21000\nبحث العلامة | Google | 4000 | 60000 | 5200 | 260 | 30000\nشوبينج | Google | 6000 | 300000 | 4100 | 120 | 15000\nفيديو قصير | TikTok | 5000 | 700000 | 8200 | 90 | 9000\nمؤثرون | Snapchat | 4500 | 250000 | 3000 | 70 | 8800',r=7),F('tr','الحد الأدنى المقبول لـ ROAS','n',2),F('cpa','أقصى CPA مقبول (ريال)','n',60)],
 r'''function compute(v){'''+PD+r'''
const R=lines(v.d).map(x=>({n:x[0],p:x[1],s:num(x[2]),i:num(x[3]),c:num(x[4]),cv:num(x[5]),rv:num(x[6])}));R.forEach(x=>{x.ctr=pct(x.c,x.i);x.cpc=x.c?x.s/x.c:0;x.cvr=pct(x.cv,x.c);x.cpa=x.cv?x.s/x.cv:0;x.roas=x.s?x.rv/x.s:0;x.cpm=x.i?x.s/x.i*1000:0;x.st=x.roas>=v.tr*1.5&&(!x.cpa||x.cpa<=v.cpa)?'scale':x.roas<v.tr||x.cpa>v.cpa?'cut':'keep'});
const T=R.reduce((a,x)=>({s:a.s+x.s,i:a.i+x.i,c:a.c+x.c,cv:a.cv+x.cv,rv:a.rv+x.rv}),{s:0,i:0,c:0,cv:0,rv:0});
const lab={scale:'🟢 وسّع',cut:'🔴 خفّض/أوقف',keep:'🟡 حافظ وحسّن'};
const rows=R.slice().sort((a,b)=>b.roas-a.roas).map(x=>[x.n,x.p,f(x.s,0),f(x.ctr)+'%',f(x.cpc),f(x.cvr)+'%',f(x.cpa),f(x.cpm),'<b>'+f(x.roas)+'x</b>',lab[x.st]]);
const P={};R.forEach(x=>{const o=P[x.p]=P[x.p]||{s:0,i:0,c:0,cv:0,rv:0};o.s+=x.s;o.i+=x.i;o.c+=x.c;o.cv+=x.cv;o.rv+=x.rv});
const prow=Object.keys(P).sort((a,b)=>P[b].rv/P[b].s-P[a].rv/P[a].s).map(k=>{const o=P[k];return[k,f(o.s,0),f(pct(o.c,o.i))+'%',f(o.c?o.s/o.c:0),f(o.cv?o.s/o.cv:0),f(o.s?o.rv/o.s:0)+'x',f(pct(o.s,T.s),1)+'%']});
const cut=R.filter(x=>x.st==='cut'),sc=R.filter(x=>x.st==='scale'),free=sum(cut.map(x=>x.s))*0.5;
const alloc=sc.length?sc.map(x=>[x.n,f(x.s,0),f(x.s+free*x.roas/sum(sc.map(y=>y.roas)),0)]):[];
const best=R.slice().sort((a,b)=>b.roas-a.roas)[0];
return kpis([kpi('إجمالي الإنفاق',f(T.s,0)),kpi('إجمالي الإيراد',f(T.rv,0)),kpi('ROAS الكلي',f(T.s?T.rv/T.s:0)+'x',T.rv/T.s>=v.tr?'good':'bad'),kpi('CPA الكلي',f(T.cv?T.s/T.cv:0)),kpi('CTR الكلي',f(pct(T.c,T.i))+'%'),kpi('أفضل حملة',best?best.n:'—')])
+'<h4>أداء كل حملة (مرتبة حسب ROAS)</h4>'+tbl(['الحملة','المنصة','الإنفاق','CTR','CPC','نسبة التحويل','CPA','CPM','ROAS','القرار'],rows)
+'<h4>أداء المنصات</h4>'+tbl(['المنصة','الإنفاق','CTR','CPC','CPA','ROAS','حصة الميزانية'],prow)
+(alloc.length?'<h4>إعادة توزيع مقترحة (نقل 50% من ميزانية الحملات الضعيفة للقوية)</h4>'+tbl(['الحملة','الإنفاق الحالي','الإنفاق المقترح'],alloc):'')
+rec([cut.length?'خفّض أو أوقف: '+cut.map(x=>x.n).join('، ')+' (ROAS أقل من '+v.tr+' أو CPA أعلى من '+v.cpa+').':'لا حملات تحتاج إيقافًا.',sc.length?'وسّع تدريجيًا (زيادة 20% كل 3 أيام): '+sc.map(x=>x.n).join('، ')+'.':'لا حملات متفوقة بعد؛ جرّب إبداعات جديدة.',R.some(x=>x.ctr<1)?'CTR أقل من 1% في بعض الحملات: غيّر الإبداع أو الاستهداف.':'معدلات النقر سليمة.',R.some(x=>x.cvr<2&&x.c>500)?'نسبة تحويل ضعيفة رغم النقرات: راجع صفحة الهبوط والعرض.':'التحويل مقبول.','اختبر إبداعًا واحدًا جديدًا أسبوعيًا للحملات الرابحة قبل إجهاد الجمهور.'])+aiOut('حلّل أداء الحملات واقترح خطة تحسين لأسبوعين: '+JSON.stringify(R.map(x=>[x.n,x.p,x.roas.toFixed(2),x.cpa.toFixed(1),x.ctr.toFixed(2)])))}''')

add('rfm-customer-segmentation','marketing','🎯','تقسيم العملاء RFM (ارفع الطلبات)','ارفع سجل الطلبات لتصنّف عملاءك: أبطال، أوفياء، معرّضون للفقد، نائمون… مع إجراء تسويقي لكل شريحة.',
 [F('d','الطلبات (عميل | تاريخ | مبلغ)','textarea','سعد | 2026-11-20 | 450\nسعد | 2026-10-15 | 300\nسعد | 2026-09-02 | 500\nنورة | 2026-11-24 | 1200\nنورة | 2026-11-01 | 900\nفهد | 2026-05-10 | 800\nهند | 2026-08-12 | 150\nهند | 2026-03-02 | 200\nخالد | 2026-11-25 | 90\nمها | 2026-02-01 | 2500\nعلي | 2026-10-30 | 60\nعلي | 2026-11-10 | 75\nعلي | 2026-11-22 | 80',r=8),F('t','تاريخ التقرير','date','2026-11-26')],
 r'''function compute(v){'''+PD+r'''
const O=lines(v.d).map(x=>({c:x[0],d:dt(x[1]),a:num(x[2])})).filter(x=>x.d);const now=dt(v.t),C={};O.forEach(o=>{const k=C[o.c]=C[o.c]||{n:o.c,r:1e9,f:0,m:0};k.r=Math.min(k.r,Math.round((now-o.d)/864e5));k.f++;k.m+=o.a});const A=Object.values(C);
const q=(arr,x,inv)=>{const s=arr.slice().sort((a,b)=>a-b);const rk=s.filter(y=>y<=x).length/s.length;const sc=Math.max(1,Math.min(5,Math.ceil(rk*5)));return inv?6-sc:sc};
const rs=A.map(x=>x.r),fs=A.map(x=>x.f),ms=A.map(x=>x.m);A.forEach(x=>{x.R=q(rs,x.r,true);x.F=q(fs,x.f);x.M=q(ms,x.m);const s=x.R*100+x.F*10+x.M;x.seg=x.R>=4&&x.F>=4?['🏆 أبطال','كافئهم: وصول مبكر وبرنامج ولاء، واطلب مراجعات وإحالات.']:x.R>=3&&x.F>=3?['💙 أوفياء','حفّز زيادة قيمة السلة: عروض حزم واشتراكات.']:x.R>=4&&x.F<=2?['🌱 جدد','رسالة ترحيب وعرض ثانٍ خلال 14 يومًا لتثبيت العادة.']:x.R<=2&&x.F>=3?['⚠️ معرّضون للفقد','حملة استعادة شخصية الآن بخصم محدود.']:x.R<=2&&x.M>=4?['💎 كبار نائمون','تواصل شخصي (اتصال/واتساب) بعرض خاص عالي القيمة.']:x.R<=2?['😴 نائمون','رسالة «اشتقنا لك» ثم أوقف الإنفاق عليهم إن لم يستجيبوا.']:['🔸 واعدون','محتوى تعليمي وعرض خفيف لرفع التكرار.']});
const G={};A.forEach(x=>{const g=G[x.seg[0]]=G[x.seg[0]]||{n:0,m:0,act:x.seg[1]};g.n++;g.m+=x.m});const tm=sum(ms);
return kpis([kpi('عملاء',A.length),kpi('طلبات',O.length),kpi('إجمالي الإيراد',f(tm,0)),kpi('متوسط الطلب',f(O.length?tm/O.length:0)),kpi('متوسط التكرار',f(mean(fs),1))])
+'<h4>الشرائح</h4>'+tbl(['الشريحة','العملاء','الإيراد','حصة الإيراد','الإجراء التسويقي'],Object.keys(G).sort((a,b)=>G[b].m-G[a].m).map(k=>[k,G[k].n,f(G[k].m,0),f(pct(G[k].m,tm),1)+'%',G[k].act]))
+'<h4>تفاصيل العملاء</h4>'+tbl(['العميل','آخر شراء (يوم)','مرات','الإنفاق','R','F','M','الشريحة'],A.sort((a,b)=>b.m-a.m).map(x=>[x.n,x.r,x.f,f(x.m,0),x.R,x.F,x.M,x.seg[0]]))
+rec(['R=حداثة الشراء، F=التكرار، M=القيمة (من 1 إلى 5، الأعلى أفضل).','أعلى 20% من العملاء غالبًا يحققون أغلب الإيراد: احمهم أولًا.','أعد حساب RFM شهريًا وتتبّع انتقال العملاء بين الشرائح.'])+aiOut('اكتب رسائل تسويقية قصيرة لكل شريحة من شرائح RFM التالية: '+Object.keys(G).join('، '))}''')

add('cohort-retention-analyzer','marketing','🔁','محلل الاحتفاظ بالعملاء (Cohort) من الطلبات','ارفع الطلبات لتعرف كم عميلًا يعود شهرًا بعد شهر لكل دفعة اكتساب.',
 [F('d','الطلبات (عميل | تاريخ)','textarea','سعد | 2026-06-03\nسعد | 2026-07-10\nسعد | 2026-09-02\nنورة | 2026-06-15\nفهد | 2026-06-20\nفهد | 2026-07-01\nهند | 2026-07-05\nهند | 2026-08-09\nهند | 2026-09-20\nخالد | 2026-07-22\nمها | 2026-08-02\nمها | 2026-09-03\nعلي | 2026-08-14\nمنى | 2026-09-09',r=8)],
 r'''function compute(v){'''+PD+r'''
const O=lines(v.d).map(x=>({c:x[0],d:dt(x[1])})).filter(x=>x.d);const mi=d=>d.getFullYear()*12+d.getMonth();const first={};O.forEach(o=>{if(!first[o.c]||mi(o.d)<first[o.c])first[o.c]=mi(o.d)});const act={};O.forEach(o=>{const co=first[o.c],k=mi(o.d)-co;act[co]=act[co]||{};(act[co][k]=act[co][k]||new Set()).add(o.c)});
const cs=Object.keys(act).map(Number).sort((a,b)=>a-b),mx=Math.max.apply(null,cs.map(c=>Math.max.apply(null,Object.keys(act[c]).map(Number))));const nm=m=>Math.floor(m/12)+'-'+String(m%12+1).padStart(2,'0');
const hdr=['الدفعة','العملاء'];for(let k=0;k<=mx;k++)hdr.push('شهر '+k);const rows=cs.map(c=>{const n=act[c][0].size,r=[nm(c),n];for(let k=0;k<=mx;k++){const s=act[c][k];r.push(s?'<span style="display:block;background:rgba(124,58,237,'+(s.size/n*.8+.05)+');color:'+(s.size/n>.5?'#fff':'#111')+';text-align:center;border-radius:4px">'+Math.round(s.size/n*100)+'%</span>':'—')}return r});
const avg=[];for(let k=1;k<=mx;k++){const xs=cs.filter(c=>act[c][0]&&(act[c][k]||k<=mx)).map(c=>(act[c][k]?act[c][k].size:0)/act[c][0].size);avg.push(['شهر '+k,f(mean(xs)*100,1)+'%'])}
const tot=Object.keys(first).length,rep=new Set(O.filter((o,i)=>O.filter(p=>p.c===o.c).length>1).map(o=>o.c)).size;
return kpis([kpi('عملاء',tot),kpi('عملاء متكررون',rep),kpi('نسبة التكرار',f(pct(rep,tot),1)+'%',pct(rep,tot)>=30?'good':'bad'),kpi('دفعات',cs.length)])+'<h4>جدول الاحتفاظ بالدفعات</h4>'+tbl(hdr,rows)+'<h4>متوسط الاحتفاظ لكل شهر</h4>'+tbl(['الشهر','متوسط الاحتفاظ'],avg)+rec(['انخفاض حاد في الشهر 1 يعني ضعف تجربة ما بعد الشراء: حسّن الرسالة الأولى والتوصيل.','قارن الدفعات: دفعة أفضل تعني حملة اكتساب أفضل، افحص مصدرها.','أطلق حملة إعادة الشراء عند نقطة الهبوط الأكبر.'])}''')

add('ab-test-significance-calculator','marketing','🧪','حاسبة اختبار A/B والدلالة الإحصائية','هل الفرق بين النسختين حقيقي؟ قيمة p، الثقة، الرفع، وحجم العينة المطلوب.',
 [F('na','زوار النسخة A','n',5000),F('ca','تحويلات A','n',150),F('nb','زوار النسخة B','n',5000),F('cb','تحويلات B','n',190),S('cl','مستوى الثقة المطلوب',[('95','95%'),('90','90%'),('99','99%')]),F('mde','أصغر تحسّن نسبي تريد كشفه %','n',15)],
 r'''function compute(v){const pa=v.ca/v.na,pb=v.cb/v.nb,p=(v.ca+v.cb)/(v.na+v.nb),se=Math.sqrt(p*(1-p)*(1/v.na+1/v.nb)),z=se?(pb-pa)/se:0;const cdf=x=>{const t=1/(1+.2316419*Math.abs(x)),d=.3989423*Math.exp(-x*x/2),pr=d*t*(.3193815+t*(-.3565638+t*(1.781478+t*(-1.821256+t*1.330274))));return x>0?1-pr:pr};const pv=2*(1-cdf(Math.abs(z))),conf=100-pv*100,need=+v.cl,sig=conf>=need,lift=pa?(pb-pa)/pa*100:0;const za=v.cl==='99'?2.576:v.cl==='90'?1.645:1.96,zb=.8416,d=pa*v.mde/100,n=d?Math.ceil(2*p*(1-p)*Math.pow(za+zb,2)/(d*d)):0;const se1=Math.sqrt(pa*(1-pa)/v.na),se2=Math.sqrt(pb*(1-pb)/v.nb);
return kpis([kpi('معدل A',f(pa*100)+'%'),kpi('معدل B',f(pb*100)+'%'),kpi('الرفع النسبي',f(lift,1)+'%',lift>0?'good':'bad'),kpi('قيمة p',f(pv,4)),kpi('الثقة',f(conf,1)+'%',sig?'good':'bad')])+'<h4>الحكم</h4>'+(sig?'<b>✅ الفرق ذو دلالة إحصائية عند '+v.cl+'%: '+(lift>0?'B أفضل من A.':'A أفضل من B.')+'</b>':'<b>⏳ لا دلالة كافية بعد. لا تعلن فائزًا.</b>')+tbl(['النسخة','زوار','تحويلات','المعدل','هامش خطأ 95%'],[['A',v.na,v.ca,f(pa*100)+'%','± '+f(1.96*se1*100)+'%'],['B',v.nb,v.cb,f(pb*100)+'%','± '+f(1.96*se2*100)+'%']])+kpis([kpi('حجم العينة المطلوب لكل نسخة',f(n,0)+' زائر'),kpi('تقدّم الاختبار',f(Math.min(100,v.na/n*100),0)+'%')])+rec([sig?'طبّق الفائز، وسجّل الدرس، وابدأ اختبارًا جديدًا.':'استمر حتى بلوغ حجم العينة، ولا توقف الاختبار عند أول فرق ظاهر.','اختبر متغيرًا واحدًا في كل مرة.','شغّل الاختبار أسبوعين كاملين على الأقل لتغطية سلوك أيام الأسبوع.'])}''')

add('ltv-cac-by-channel','marketing','💎','تحليل LTV وCAC لكل قناة اكتساب','قارن قنواتك بقيمة العميل مدى الحياة وتكلفة اكتسابه وفترة الاسترداد.',
 [F('d','القنوات (قناة | إنفاق | عملاء جدد | متوسط الطلب | طلبات/سنة | هامش % | عمر العميل بالسنوات)','textarea','Meta | 20000 | 300 | 180 | 3 | 35 | 1.5\nGoogle | 15000 | 160 | 260 | 3.5 | 38 | 2\nTikTok | 12000 | 150 | 120 | 2 | 30 | 1\nمؤثرون | 10000 | 90 | 200 | 2.5 | 35 | 1.5\nعضوي/SEO | 4000 | 220 | 230 | 4 | 40 | 2.5\nإحالات | 2000 | 80 | 250 | 4.5 | 40 | 3',r=7)],
 r'''function compute(v){'''+PD+r'''
const R=lines(v.d).map(x=>{const s=num(x[1]),n=num(x[2]),a=num(x[3]),o=num(x[4]),m=num(x[5])/100,l=num(x[6]),cac=n?s/n:0,ltv=a*o*l*m,mo=a*o/12*m;return{n:x[0],s,cn:n,cac,ltv,r:cac?ltv/cac:0,pb:mo?cac/mo:0}});
const T=R.reduce((a,x)=>({s:a.s+x.s,n:a.n+x.cn,v:a.v+x.ltv*x.cn}),{s:0,n:0,v:0});
const vd=x=>x.r>=3?'🟢 ممتاز':x.r>=1.5?'🟡 مقبول':'🔴 خاسر';
return kpis([kpi('CAC المتوسط',f(T.n?T.s/T.n:0)),kpi('LTV المتوسط',f(T.n?T.v/T.n:0)),kpi('LTV/CAC',f(T.s?T.v/T.s:0)+'x',T.v/T.s>=3?'good':'bad'),kpi('عملاء جدد',T.n)])+tbl(['القناة','الإنفاق','عملاء','CAC','LTV','LTV/CAC','الاسترداد (شهر)','الحكم'],R.sort((a,b)=>b.r-a.r).map(x=>[x.n,f(x.s,0),x.cn,f(x.cac),f(x.ltv),'<b>'+f(x.r)+'x</b>',f(x.pb,1),vd(x)]))+rec(['نسبة LTV/CAC الصحية 3x فأكثر، والاسترداد أقل من 12 شهرًا.','وسّع القنوات الخضراء، واختبر خفض تكلفة الحمراء قبل إيقافها.','حسّن LTV بالتكرار (ولاء، اشتراك) لا بخفض CAC فقط.'])+aiOut('اقترح خطة توزيع ميزانية اكتساب بناءً على LTV/CAC: '+JSON.stringify(R.map(x=>[x.n,x.cac.toFixed(0),x.ltv.toFixed(0)])))}''')

add('content-performance-analyzer','marketing','📱','محلل أداء المحتوى والمنشورات (ارفع تقرير المنصات)','ارفع تقرير المنشورات لتعرف أي نوع وموضوع ومنصة يحقق أعلى تفاعل، وما الذي تكرره.',
 [F('d','المنشورات (عنوان | منصة | نوع | وصول | إعجاب | تعليق | مشاركة | نقرات)','textarea','5 أخطاء في الإعلان | Instagram | ريلز | 42000 | 3100 | 210 | 480 | 650\nقصة عميل | Instagram | صورة | 9000 | 520 | 40 | 30 | 90\nكيف تختار المنتج | TikTok | فيديو | 80000 | 5400 | 320 | 900 | 1200\nعرض الأسبوع | X | نص | 6000 | 150 | 12 | 40 | 200\nدليل الشراء | LinkedIn | مقال | 7000 | 380 | 55 | 120 | 400\nكواليس | Instagram | ريلز | 30000 | 2800 | 190 | 300 | 310',r=7)],
 r'''function compute(v){'''+PD+r'''
const R=lines(v.d).map(x=>{const r=num(x[3]),l=num(x[4]),c=num(x[5]),s=num(x[6]),k=num(x[7]),e=l+c*2+s*3;return{n:x[0],p:x[1],t:x[2],r:r,e:e,er:pct(e,r),ctr:pct(k,r),k:k,sv:pct(s,r)}});
const g=(key)=>{const o={};R.forEach(x=>{const a=o[x[key]]=o[x[key]]||{n:0,r:0,e:0,k:0};a.n++;a.r+=x.r;a.e+=x.e;a.k+=x.k});return Object.keys(o).map(k=>({k:k,n:o[k].n,r:o[k].r,er:pct(o[k].e,o[k].r),ctr:pct(o[k].k,o[k].r)})).sort((a,b)=>b.er-a.er)};
const gp=g('p'),gt=g('t'),top=R.slice().sort((a,b)=>b.er-a.er);
return kpis([kpi('منشورات',R.length),kpi('إجمالي الوصول',f(sum(R.map(x=>x.r)),0)),kpi('متوسط التفاعل',f(mean(R.map(x=>x.er)))+'%'),kpi('أفضل نوع',gt[0]?gt[0].k:'—'),kpi('أفضل منصة',gp[0]?gp[0].k:'—')])
+'<h4>ترتيب المنشورات</h4>'+tbl(['المنشور','المنصة','النوع','وصول','تفاعل مرجّح','معدل التفاعل','CTR','مشاركات/وصول'],top.map(x=>[x.n,x.p,x.t,f(x.r,0),f(x.e,0),f(x.er)+'%',f(x.ctr)+'%',f(x.sv)+'%']))
+'<h4>حسب المنصة</h4>'+tbl(['المنصة','منشورات','وصول','معدل التفاعل','CTR'],gp.map(x=>[x.k,x.n,f(x.r,0),f(x.er)+'%',f(x.ctr)+'%']))
+'<h4>حسب نوع المحتوى</h4>'+tbl(['النوع','منشورات','وصول','معدل التفاعل','CTR'],gt.map(x=>[x.k,x.n,f(x.r,0),f(x.er)+'%',f(x.ctr)+'%']))
+rec(['كرّر صيغة «'+(top[0]?top[0].n:'')+'» بزوايا جديدة.','ضاعف النوع الأعلى تفاعلًا ('+(gt[0]?gt[0].k:'')+') وقلّل الأضعف.','المشاركات أقوى إشارة انتشار: اصنع محتوى «يستحق الإرسال لصديق».','المنصات ذات CTR المنخفض تحتاج دعوة إجراء أوضح.'])+aiOut('اقترح 10 أفكار محتوى جديدة بنفس نمط أفضل المنشورات: '+JSON.stringify(top.slice(0,3).map(x=>[x.n,x.t,x.p])))}''')

add('best-time-to-post','marketing','🕒','أفضل وقت للنشر من بياناتك','ارفع تاريخ ووقت منشوراتك وتفاعلها ليحدد أفضل أيام وساعات النشر لجمهورك.',
 [F('d','المنشورات (تاريخ ووقت | تفاعل)','textarea','2026-11-02 20:30 | 420\n2026-11-03 09:00 | 90\n2026-11-04 21:00 | 510\n2026-11-05 13:00 | 150\n2026-11-06 22:00 | 380\n2026-11-08 20:00 | 600\n2026-11-09 08:30 | 70\n2026-11-10 21:30 | 480\n2026-11-12 12:30 | 140\n2026-11-14 20:45 | 560\n2026-11-15 10:00 | 200\n2026-11-17 21:00 | 450',r=8)],
 r'''function compute(v){'''+PD+r'''
const R=lines(v.d).map(x=>({d:dt(String(x[0]).replace(' ','T')),e:num(x[1])})).filter(x=>x.d);const DN=['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];const dd={},hh={},bk={};R.forEach(x=>{const d=x.d.getDay(),h=x.d.getHours(),b=h<6?'فجرًا (0-6)':h<12?'صباحًا (6-12)':h<17?'ظهرًا (12-17)':h<21?'مساءً (17-21)':'ليلًا (21-24)';[[dd,DN[d]],[hh,h+':00'],[bk,b]].forEach(a=>{const o=a[0][a[1]]=a[0][a[1]]||{n:0,e:0};o.n++;o.e+=x.e})});
const rk=o=>Object.keys(o).map(k=>[k,o[k].n,o[k].e/o[k].n]).sort((a,b)=>b[2]-a[2]);const avg=mean(R.map(x=>x.e));const d=rk(dd),h=rk(hh),b=rk(bk);const tb=a=>a.map(x=>[x[0],x[1],f(x[2],0),f(x[2]/avg*100-100,0)+'%']);
return kpis([kpi('منشورات',R.length),kpi('متوسط التفاعل',f(avg,0)),kpi('أفضل يوم',d[0]?d[0][0]:'—','good'),kpi('أفضل ساعة',h[0]?h[0][0]:'—','good'),kpi('أفضل فترة',b[0]?b[0][0]:'—')])+'<h4>حسب اليوم</h4>'+tbl(['اليوم','منشورات','متوسط التفاعل','مقارنة بالمتوسط'],tb(d))+'<h4>حسب الفترة</h4>'+tbl(['الفترة','منشورات','متوسط التفاعل','مقارنة بالمتوسط'],tb(b))+'<h4>حسب الساعة</h4>'+tbl(['الساعة','منشورات','متوسط التفاعل','مقارنة بالمتوسط'],tb(h))+rec(['انشر أهم محتواك في '+(d[0]?d[0][0]:'')+' عند '+(h[0]?h[0][0]:'')+'.','العينة الصغيرة تضلّل: اجمع 30 منشورًا على الأقل لنتائج أدق.','اختبر الفترات الضعيفة لعدد كافٍ من المنشورات قبل استبعادها.'])}''')

add('survey-driver-analyzer','market','📋','محلل نتائج الاستبيان وعوامل الرضا (ارفع الردود)','ارفع ردود الاستبيان (مقياس 1-5) لتحصل على المتوسطات وأعلى درجتين وأهم العوامل المؤثرة في الرضا العام.',
 [F('h','أسماء الأسئلة (مفصولة بـ |) — آخر سؤال = الرضا العام','textarea','جودة المنتج | سرعة التوصيل | السعر | خدمة العملاء | الرضا العام',r=2),F('d','الردود (كل سطر مستجيب: درجات مفصولة بـ |)','textarea','5 | 4 | 3 | 5 | 5\n4 | 2 | 3 | 4 | 4\n5 | 5 | 4 | 5 | 5\n3 | 2 | 2 | 3 | 3\n4 | 3 | 4 | 4 | 4\n2 | 1 | 3 | 2 | 2\n5 | 4 | 3 | 5 | 5\n4 | 4 | 5 | 4 | 4\n3 | 2 | 3 | 2 | 3\n5 | 5 | 4 | 4 | 5',r=9)],
 r'''function compute(v){'''+PD+r'''
const H=String(v.h).split('|').map(x=>x.trim()).filter(Boolean),R=lines(v.d).map(r=>r.map(num)).filter(r=>r.length>=H.length&&r.every(x=>!isNaN(x)));const n=R.length,k=H.length-1,col=i=>R.map(r=>r[i]);const corr=(a,b)=>{const ma=mean(a),mb=mean(b);const nu=sum(a.map((x,i)=>(x-ma)*(b[i]-mb)));const de=Math.sqrt(sum(a.map(x=>(x-ma)**2))*sum(b.map(x=>(x-mb)**2)));return de?nu/de:0};const ov=col(k);
const rows=H.map((h,i)=>{const c=col(i);return{h:h,m:mean(c),sd:sd(c),t2:pct(c.filter(x=>x>=4).length,n),b2:pct(c.filter(x=>x<=2).length,n),r:i<k?corr(c,ov):null}});
const drv=rows.slice(0,k).sort((a,b)=>b.r-a.r);const mat=drv.map(x=>[x.h,f(x.m),f(x.r),x.m<mean(rows.slice(0,k).map(y=>y.m))&&x.r>mean(drv.map(y=>y.r))?'🔴 أولوية تحسين (مهم وضعيف)':x.m>=mean(rows.slice(0,k).map(y=>y.m))&&x.r>mean(drv.map(y=>y.r))?'🟢 حافظ (مهم وقوي)':x.m<mean(rows.slice(0,k).map(y=>y.m))?'🟡 مراقبة':'⚪ أقل أهمية']);
return kpis([kpi('مستجيبون',n),kpi('متوسط الرضا العام',f(rows[k].m)+' / 5',rows[k].m>=4?'good':'bad'),kpi('راضون (4-5)',f(rows[k].t2,0)+'%'),kpi('غير راضين (1-2)',f(rows[k].b2,0)+'%',rows[k].b2>15?'bad':'good')])+'<h4>نتائج كل سؤال</h4>'+tbl(['السؤال','المتوسط','الانحراف','أعلى درجتين %','أدنى درجتين %','ارتباط بالرضا'],rows.map(r=>[r.h,f(r.m),f(r.sd),f(r.t2,0)+'%',f(r.b2,0)+'%',r.r==null?'—':f(r.r)]))+'<h4>مصفوفة الأولويات (الأهمية × الأداء)</h4>'+tbl(['العامل','الأداء (متوسط)','الأهمية (ارتباط)','التصنيف'],mat)+rec(['ركّز أولًا على العوامل «🔴 أولوية تحسين»: لها أكبر أثر على الرضا وأداؤها أضعف.','الارتباط ليس سببًا مؤكدًا؛ تحقق بمقابلات قصيرة مع العملاء.','حجم العينة '+n+(n<30?' صغير جدًا: النتائج استرشادية فقط.':' مقبول.')])}''')

add('price-elasticity-estimator','market','📉','مقدّر مرونة السعر والسعر الأمثل','أدخل أسعارًا جرّبتها ومبيعاتها لتقدير مرونة الطلب والسعر الذي يعظّم الإيراد أو الربح.',
 [F('d','التجارب (سعر | كمية مباعة)','textarea','80 | 520\n90 | 450\n100 | 400\n110 | 320\n120 | 270\n130 | 210',r=6),F('c','تكلفة الوحدة','n',55)],
 r'''function compute(v){'''+PD+r'''
const R=lines(v.d).map(x=>[num(x[0]),num(x[1])]).filter(x=>x[0]>0&&x[1]>0);const lx=R.map(x=>Math.log(x[0])),ly=R.map(x=>Math.log(x[1])),mx=mean(lx),my=mean(ly);const b=sum(lx.map((x,i)=>(x-mx)*(ly[i]-my)))/sum(lx.map(x=>(x-mx)**2)),a=my-b*mx;const ss=sum(ly.map((y,i)=>(y-(a+b*lx[i]))**2)),st=sum(ly.map(y=>(y-my)**2)),r2=st?1-ss/st:0;
const q=p=>Math.exp(a)*Math.pow(p,b);const lo=Math.min.apply(null,R.map(x=>x[0]))*.7,hi=Math.max.apply(null,R.map(x=>x[0]))*1.5;let bp=0,bpv=-1e18,br=0,brv=-1e18;const grid=[];for(let p=lo;p<=hi;p+=(hi-lo)/60){const Q=q(p),rv=p*Q,pf=(p-v.c)*Q;if(pf>bpv){bpv=pf;bp=p}if(rv>brv){brv=rv;br=p}grid.push([p,Q,rv,pf])}
const el=b,opt=el<-1?v.c*el/(1+el):null;
return kpis([kpi('مرونة الطلب',f(el),el<-1?'good':'bad'),kpi('دقة النموذج R²',f(r2)),kpi('السعر الأمثل للربح',f(bp),'good'),kpi('ربح متوقع',f(bpv,0)),kpi('سعر أعلى إيراد',f(br))])+'<h4>التفسير</h4><p>'+(el<-1?'الطلب مرن: رفع السعر 1% يقلل الكمية أكثر من '+f(-el,2)+'%. الأفضل غالبًا الاقتراب من السعر الأمثل للربح.':'الطلب غير مرن: رفع السعر يزيد الإيراد ولا يقلل الكمية بنفس النسبة؛ جرّب رفعًا تدريجيًا.')+'</p>'+tbl(['السعر','كمية متوقعة','الإيراد','الربح'],grid.filter((x,i)=>i%6===0).map(x=>[f(x[0]),f(x[1],0),f(x[2],0),f(x[3],0)]))+rec(['النموذج بسيط (مرونة ثابتة): اختبر السعر الجديد على جزء من الزبائن أولًا.','دقة R² أقل من 0.7 تعني أن عوامل أخرى (موسم، منافسة) تؤثر: لا تعتمد النتيجة وحدها.','لا تقل عن التكلفة مع هامش يغطي التشغيل.'])}''')

add('survey-sample-size-calculator','market','🧮','حاسبة حجم العينة لدراسة السوق','كم مستجيبًا تحتاج لنتائج موثوقة؟ مع هامش الخطأ ومستوى الثقة وحجم المجتمع.',
 [F('N','حجم المجتمع (0 = كبير جدًا)','n',0),S('cl','مستوى الثقة',[('1.96','95%'),('1.645','90%'),('2.576','99%')]),F('e','هامش الخطأ %','n',5),F('p','النسبة المتوقعة %','n',50),F('rr','نسبة الاستجابة المتوقعة %','n',20)],
 r'''function compute(v){const z=+v.cl,p=v.p/100,e=v.e/100;let n0=z*z*p*(1-p)/(e*e);const n=v.N>0?n0/(1+(n0-1)/v.N):n0;const N=Math.ceil(n),inv=Math.ceil(N/(v.rr/100));const rows=[1,2,3,5,7,10].map(m=>{const x=Math.ceil((v.N>0?(z*z*p*(1-p)/((m/100)**2))/(1+((z*z*p*(1-p)/((m/100)**2))-1)/v.N):z*z*p*(1-p)/((m/100)**2)));return[m+'%',x]});return kpis([kpi('العينة المطلوبة',f(N,0),'good'),kpi('دعوات لازمة',f(inv,0)),kpi('هامش الخطأ',v.e+'%')])+tbl(['هامش خطأ','عينة مطلوبة'],rows)+rec(['استخدم نسبة 50% عند عدم وجود تقدير مسبق (أكبر عينة آمنة).','العينة العشوائية أهم من الحجم: عيّنة متحيزة كبيرة تضلّل.','قسّم العينة على الشرائح إن أردت تحليل كل شريحة على حدة.'])}''')

add('rice-prioritization','marketing','🏁','ترتيب أولويات المبادرات (RICE)','رتّب أفكار التسويق والمنتج بحسب الوصول والأثر والثقة والجهد، بشكل موضوعي.',
 [F('d','المبادرات (فكرة | وصول | أثر 0.25-3 | ثقة % | جهد بأسابيع)','textarea','قسيمة ترحيب | 4000 | 1 | 80 | 1\nبرنامج ولاء | 2500 | 2 | 60 | 6\nإعادة تصميم صفحة المنتج | 9000 | 1 | 70 | 3\nحملة مؤثرين | 15000 | 0.5 | 40 | 4\nسلة مهجورة آلية | 3000 | 2 | 85 | 2',r=6)],
 r'''function compute(v){const R=lines(v.d).map(x=>{const r=num(x[1]),i=num(x[2]),c=num(x[3])/100,e=num(x[4]);return{n:x[0],r:r,i:i,c:c*100,e:e,s:e?r*i*c/e:0}}).sort((a,b)=>b.s-a.s);const mx=R[0]?R[0].s:1;return tbl(['الترتيب','المبادرة','وصول','أثر','ثقة','جهد','نقاط RICE','الأولوية'],R.map((x,i)=>[i+1,x.n,f(x.r,0),x.i,x.c+'%',x.e,'<b>'+f(x.s,0)+'</b>',i<2?'🟢 ابدأ الآن':i<4?'🟡 التالي':'⚪ لاحقًا']))+rec(['RICE = (الوصول × الأثر × الثقة) ÷ الجهد.','المبادرات ذات الثقة المنخفضة اختبرها بتجربة صغيرة قبل الاستثمار.','أعد الترتيب كل ربع سنة.'])}''')

add('abc-pareto-analysis','sales','📊','تحليل ABC وباريتو للمنتجات والعملاء (ارفع المبيعات)','صنّف منتجاتك أو عملاءك إلى A وB وC حسب مساهمتها في الإيراد، لتعرف أين تركّز.',
 [F('d','البنود (اسم | إيراد)','textarea','منتج 1 | 120000\nمنتج 2 | 80000\nمنتج 3 | 40000\nمنتج 4 | 25000\nمنتج 5 | 15000\nمنتج 6 | 9000\nمنتج 7 | 6000\nمنتج 8 | 3000\nمنتج 9 | 1500\nمنتج 10 | 500',r=8),F('a','حد الفئة A (% تراكمي)','n',70),F('b','حد الفئة B (% تراكمي)','n',90)],
 r'''function compute(v){'''+PD+r'''
const R=lines(v.d).map(x=>({n:x[0],a:num(x[1])})).filter(x=>x.a>0).sort((a,b)=>b.a-a.a),T=sum(R.map(x=>x.a));let c=0;R.forEach((x,i)=>{const before=c;c+=x.a;x.cum=c/T*100;x.cl=before/T*100<v.a?'A':before/T*100<v.b?'B':'C'});const G={A:[],B:[],C:[]};R.forEach(x=>G[x.cl].push(x));const row=k=>[k,G[k].length,f(pct(G[k].length,R.length),0)+'%',f(sum(G[k].map(x=>x.a)),0),f(pct(sum(G[k].map(x=>x.a)),T),1)+'%'];
return kpis([kpi('إجمالي الإيراد',f(T,0)),kpi('بنود A',G.A.length+' ('+f(pct(sum(G.A.map(x=>x.a)),T),0)+'% من الإيراد)','good'),kpi('بنود C',G.C.length+' ('+f(pct(sum(G.C.map(x=>x.a)),T),1)+'%)')])+tbl(['الفئة','عدد','% من البنود','الإيراد','% من الإيراد'],['A','B','C'].map(row))+'<h4>التفاصيل</h4>'+tbl(['البند','الإيراد','% تراكمي','الفئة'],R.map(x=>[x.n,f(x.a,0),f(x.cum,1)+'%','<b>'+x.cl+'</b>']))+rec(['A: احمِ مخزونها وجودتها وسعرها واهتم بأصحابها بشكل خاص.','B: حسّن تدريجيًا ببيع متقاطع.','C: راجع الإبقاء عليها؛ قد تستهلك مخزونًا وتشتت الاهتمام.'])}''')

add('sales-seasonal-forecast','sales','📆','توقّع المبيعات بالموسمية والاتجاه (ارفع المبيعات الشهرية)','ارفع مبيعات شهرية لتحصل على مؤشرات الموسمية والاتجاه وتوقع الأشهر القادمة.',
 [F('d','المبيعات الشهرية (شهر | مبلغ) — سنة فأكثر','textarea','2025-01 | 80000\n2025-02 | 76000\n2025-03 | 95000\n2025-04 | 90000\n2025-05 | 88000\n2025-06 | 85000\n2025-07 | 82000\n2025-08 | 86000\n2025-09 | 92000\n2025-10 | 105000\n2025-11 | 160000\n2025-12 | 140000\n2026-01 | 92000\n2026-02 | 88000\n2026-03 | 108000\n2026-04 | 103000\n2026-05 | 101000\n2026-06 | 98000',r=10),F('h','أشهر التوقع','n',6)],
 r'''function compute(v){'''+PD+r'''
const R=lines(v.d).map(x=>({m:x[0],a:num(x[1])})).filter(x=>/^\d{4}-\d{2}/.test(x.m)&&x.a>=0).sort((a,b)=>a.m<b.m?-1:1);const n=R.length,xs=R.map((x,i)=>i),ys=R.map(x=>x.a),mx=mean(xs),my=mean(ys);const b=sum(xs.map((x,i)=>(x-mx)*(ys[i]-my)))/sum(xs.map(x=>(x-mx)**2)),a=my-b*mx;const MN=['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];const si={};R.forEach((x,i)=>{const k=+x.m.slice(5,7)-1;(si[k]=si[k]||[]).push(x.a/Math.max(1,a+b*i))});const idx=k=>si[k]?mean(si[k]):1;const last=R[n-1].m,ly=+last.slice(0,4),lm=+last.slice(5,7)-1;const F2=[];for(let i=1;i<=v.h;i++){const mm=(lm+i)%12,yy=ly+Math.floor((lm+i)/12),val=Math.max(0,(a+b*(n-1+i))*idx(mm));F2.push([yy+'-'+String(mm+1).padStart(2,'0'),MN[mm],f(val,0),f(idx(mm),2)])}const tot=sum(F2.map(x=>num(x[2].replace(/,/g,''))));
const hi=Object.keys(si).map(Number).sort((p,q)=>idx(q)-idx(p));
return kpis([kpi('الاتجاه الشهري',f(b,0)+' /شهر',b>=0?'good':'bad'),kpi('أقوى شهر موسميًا',MN[hi[0]]||'—'),kpi('أضعف شهر',MN[hi[hi.length-1]]||'—'),kpi('إجمالي التوقع',f(tot,0))])+'<h4>التوقعات</h4>'+tbl(['الشهر','الاسم','المبيعات المتوقعة','مؤشر الموسمية'],F2)+'<h4>مؤشرات الموسمية (1.00 = متوسط)</h4>'+tbl(['الشهر','المؤشر'],Object.keys(si).map(Number).sort((p,q)=>p-q).map(k=>[MN[k],f(idx(k),2)]))+rec(['المؤشر أعلى من 1 يعني موسم قوي: جهّز المخزون والإعلان قبله بشهر.','كل ما زادت سنوات البيانات زادت دقة الموسمية (يوصى بسنتين+).','قارن التوقع بالفعلي شهريًا وعدّل الخطة.'])+aiOut('اقترح خطة مخزون وتسويق حسب الموسمية: '+JSON.stringify(F2.map(x=>[x[1],x[2]])))}''')

